    body: "■ 오늘의 큰 그림\n\n9월 11일 금요일 아침 브리핑입니다. 전일은 9월 10일 종가입니다.\n\n코스피가 7,033.92로 17.72포인트(0.25%) 내리며 종가 7,000선을 지켰습니다. 시가 7,038.85, 장중 저점 6,898.45입니다. 코스닥은 836.92(+0.79%)입니다.\n\n외국인이 2조 4,820억 원을 순매도했습니다. 개인 3,801억·기관 4,334억 매수, 기타법인 1조 6,670억 매수입니다. 네 마녀의 날과 반도체 지수 리밸런싱이 겹쳤습니다.\n\n삼성전자는 269,000원(−0.19%)으로 장중 263,500원을 되돌렸습니다. 하이닉스는 1,853,000원(−0.16%), 장중 1,890,000~1,811,000원입니다. 자사주 방파제와 종가를 나누시기 바랍니다.\n\n엘지에너지솔루션 365,000(−1.62%), 삼성바이오로직스 1,423,000(−2.00%), 현대차 389,000(+0.26%)로 온도가 달랐습니다. 브렌트 101달러·미국 10년 4.92%가 같은 화면입니다.\n\n숫자는 전일 종가·거래소 집계 기준입니다. 하루 헤드라인을 전 업종 전환으로 쓰지 마시기 바랍니다.\n\n■ 앞으로 볼 것\n\n(1) 7,000선 종가 유지와 장중 6,898 저점 대비 되돌림을 확인하시기 바랍니다.\n\n(2) 외국인 연속 매도와 기타법인 자사주를 보시면 됩니다.\n\n(3) 미국 소비자물가·9월 16일 회의를 표에 두시기 바랍니다.\n\n(4) 엔솔·바이오 상대 성과를 적으시기 바랍니다.\n\n(5) 삼성·하이닉스 약보합이 수급인지 업종인지 나누시면 됩니다.\n\n■ 투자 시사점\n\n한장요약은 체크리스트입니다. 개별 종목 리포트로 내려가 종가와 수급을 확인하시기 바랍니다.\n\n유가·금리 앞에서 레버리지는 보수적으로 두시기 바랍니다.\n\n반도체 약보합을 완성차·바이오까지 같은 베타로 읽지 마시기 바랍니다.\n\ninvestus.kr SRP 최고투자책임자 발행",
