    body: "■ 무슨 일인가요\n\n코스피가 7,033.92로 17.72포인트(0.25%) 내리며 종가 7,000선을 지켰습니다. 시가는 7,038.85, 장중 저점은 6,898.45입니다.\n\n코스닥은 836.92(+0.79%)입니다. 코스닥에서 기관이 1조 3,488억 원을 순매수하고 외국인은 1조 756억 원을 순매도했습니다.\n\n유가증권에서 외국인 2조 4,820억 순매도, 개인 3,801억·기관 4,334억 순매수입니다. 기관은 6거래일 연속 매수, 개인은 6거래일 만에 매수 우위입니다.\n\n코스피 숫자는 오늘 표에만 유효합니다. 집계 시각이 바뀌면 같은 지표라도 칸을 나누시기 바랍니다. 속보 한 줄과 확정 집계를 같은 가중치로 두지 마시기 바랍니다.\n\n■ 조금만 더 알려드리면\n\n기타법인 1조 6,670억 순매수는 삼성·하이닉스 자사주가 포함된 칸입니다. 외국인 매도와 지수 방어를 한 문장에 합치지 마시기 바랍니다.\n\n선물·옵션 동시 만기와 반도체 지수 리밸런싱이 변동성을 키웠다는 설명이 있습니다. 브렌트 101달러·미국 10년 4.92%가 하방 요인으로 거론됐습니다.\n\n코스피 칸에서는 종가·수급·공시의 정의를 먼저 고정하시기 바랍니다. 후속 종가가 나오기 전에는 모델에 넣는 값을 보수적으로 두시기 바랍니다. 단위가 바뀌면 표를 새로 만드시기 바랍니다. 공개 범위와 확정 공시를 같은 가중치로 두지 마시기 바랍니다. 출처 이름보다 숫자 정의가 먼저입니다.\n\n어제 칸과 오늘 칸을 덮어쓰지 마시기 바랍니다. 코스피 후속 일정이 비어 있으면 가정 가중치를 낮추시기 바랍니다.\n\n■ 장기적으로 보면\n\n코스피는 반도체 비중과 외국인 지분이 큰 지수입니다. 7,000선은 심리면이지 펀더멘털 스위치가 아닙니다.\n\n3~5년 뷰에서 이익과 환율이 지수를 결정합니다. 오늘 수급은 그 궤적의 하루입니다.\n\n시간이 지나면 코스피 축도 반복 측정되는 지표가 쌓입니다. 그때 가정의 가중치를 올리시면 됩니다. 지금은 스냅샷을 칸에 남기는 단계입니다. 한 번의 등락으로 중기 결론을 내지 마시기 바랍니다.\n\n■ 투자 시사점\n\n7,033.92와 6,898 저점은 「종가 사수」 칸입니다. 외국인 2.48조 매도와 같이 적으시기 바랍니다.\n\n자사주 방파제를 추세 전환으로 읽지 마시기 바랍니다. 물가 주간에 지수 레버리지를 키우지 마시기 바랍니다.\n\n코스피 이슈는 해당 표에서만 추적하시기 바랍니다. 다른 시장 헤드라인과 섞어 한 방향 베팅을 만들지 마시기 바랍니다. 빈칸 지표가 채워지기 전에는 확정 결론을 미루시기 바랍니다.\n\ninvestus.kr SRP 최고투자책임자 발행",
