    summary: "전일 대비 0.16% 내린 1,853,000원입니다. 장중 고점 1,890,000원, 저점 1,811,000원입니다. 기관이 5,615억 원을 샀고 외국인은 1조 7,797억 원을 팔았습니다. 리밸런싱 매물이 겹쳤다는 설명이 있습니다. 삼성 −0.19%와 온도를 비교하시기 바랍니다.",
    body: "■ 무슨 일인가요\n\n하이닉스가 1,853,000원으로 0.16% 내리며 마감했습니다. 장중 1,890,000원까지 올랐다 1,811,000원까지 밀렸습니다.\n\n기관이 5,615억 원을 순매수하고 외국인은 1조 7,797억 원을 순매도했습니다. 개인은 1,079억 원 순매수였습니다.\n\n반도체 지수 리밸런싱이 대형주 매물을 키웠다는 설명이 있습니다. 종가 약보합과 칸을 나누시기 바랍니다.\n\nSK하이닉스 숫자는 오늘 표에만 유효합니다. 집계 시각이 바뀌면 같은 지표라도 칸을 나누시기 바랍니다. 속보 한 줄과 확정 집계를 같은 가중치로 두지 마시기 바랍니다.\n\n■ 조금만 더 알려드리면\n\n대만 TSMC 8월 매출 최대 뉴스가 장중 반등 재료로 거론됐습니다. 하루 종가의 원인으로 단정하지 마시기 바랍니다.\n\n자사주 방파제는 기타법인 칸입니다. 외국인 매도를 추세 전환으로 읽지 마시기 바랍니다.\n\nSK하이닉스 칸에서는 종가·수급·공시의 정의를 먼저 고정하시기 바랍니다. 후속 종가가 나오기 전에는 모델에 넣는 값을 보수적으로 두시기 바랍니다. 단위가 바뀌면 표를 새로 만드시기 바랍니다. 공개 범위와 확정 공시를 같은 가중치로 두지 마시기 바랍니다. 출처 이름보다 숫자 정의가 먼저입니다.\n\n어제 칸과 오늘 칸을 덮어쓰지 마시기 바랍니다. SK하이닉스 후속 일정이 비어 있으면 가정 가중치를 낮추시기 바랍니다.\n\n■ 장기적으로 보면\n\n고대역폭 메모리 점유가 해자입니다. 오늘 수급은 그 궤적의 하루입니다.\n\n고객 집중과 가격 사이클이 중기 리스크입니다. 하루 저점을 바닥으로 쓰지 마시기 바랍니다.\n\n시간이 지나면 SK하이닉스 축도 반복 측정되는 지표가 쌓입니다. 그때 가정의 가중치를 올리시면 됩니다. 지금은 스냅샷을 칸에 남기는 단계입니다. 한 번의 등락으로 중기 결론을 내지 마시기 바랍니다.\n\n■ 투자 시사점\n\n1,853,000원과 1,811,000원은 「종가·저점」 칸입니다. 외국인 1.78조 매도와 같이 적으시기 바랍니다.\n\n리밸런싱 하루를 수급 안도로 읽지 마시기 바랍니다. 물가 주간에 추격하지 마시기 바랍니다.\n\nSK하이닉스 이슈는 해당 표에서만 추적하시기 바랍니다. 다른 시장 헤드라인과 섞어 한 방향 베팅을 만들지 마시기 바랍니다. 빈칸 지표가 채워지기 전에는 확정 결론을 미루시기 바랍니다.\n\ninvestus.kr SRP 최고투자책임자 발행",
    titleEn: "Hynix closed 1,853,000 (−0.16%) after an intraday low of 1,811,000",
    summaryEn: "Close 1,853,000 (−0.16%), high 1,890,000, low 1,811,000. Inst +₩561.5B, foreign −₩1.7797T.",
    bodyEn: "See Korean body.\n\ninvestus.kr SRP Chief Investment Officer",
