    summary: "종가 348,500원(−3.86%)입니다. 유가·금리·위험회피가 배터리·자동차 체인을 같이 누른 날로 읽힙니다. −3.86%는 반도체보다 큰 조정입니다. 전기차 수요·메탈 원가·금리 할인을 한 줄로 합치지 마시기 바랍니다.",
    body: "■ 상세\n\n종가 348,500원(−3.86%)입니다. 유가·금리·위험회피가 배터리·자동차 체인을 같이 누른 날로 읽힙니다. −3.86%는 반도체보다 큰 조정입니다. 전기차 수요·메탈 원가·금리 할인을 한 줄로 합치지 마시기 바랍니다.\n\n핵심 히어로 숫자는 「−3.86%」입니다. 정의(기간·단위·잠정/확정)를 칸으로 나누어 적으시기 바랍니다. 같은 날의 다른 지표와 한 문장으로 합치지 마시기 바랍니다.\n\n배터리 개별 수주·가동률과 업종 베타를 칸으로 나누시기 바랍니다. 다음 확인은 완성차 판매·원재료 가격입니다. 장기적으로 에너지 저장·전기차 침투가 해자 논쟁입니다. 수급·정책·가격을 역할별로 분리해 두면 헤드라인 착시가 줄어듭니다.\n\n다음 확인할 것은 후속 종가·공시·캘린더 이벤트입니다. 단발 등락만으로 중기 결론을 내지 마시기 바랍니다.\n\n■ 왜 이 뉴스가 중요한가\n\n1. 가격·수급이 포트폴리오 베타를 즉시 바꿉니다. −3.86%가 반복되면 비중 조정의 입력이 됩니다. 시계열로만 판단하시기 바랍니다.\n\n2. 업종·자산 간 상대 성과를 같은 표에 두면 로테이션이 보입니다. 한 티커만 보고 시장 전체를 단정하지 마시기 바랍니다.\n\n3. 정책·리밸런싱·회의 일정이 있으면 그 날짜가 변동성 스위치입니다. 캘린더에 고정하시기 바랍니다.\n\n4. 아직 빈칸인 마진·가동률·대출 한도를 명시하면 과해석을 줄일 수 있습니다.\n\n5. 장기적으로는 사이클·제도·인구가 가격보다 느리게 움직입니다. 오늘 숫자는 그 궤적의 한 점입니다.\n\n■ 시나리오\n\n**가: 실측이 히어로 숫자를 뒷받침하고 수급이 같은 방향이면 추세 연장 시나리오가 열립니다.**\n**나: 캘린더 이벤트가 반대로 읽히면 되돌림이 커질 수 있습니다. 레버리지부터 줄이시기 바랍니다.**\n**다: 업종만 갈리면 지수·개별이 어긋날 수 있습니다. 상대 성과 표를 유지하시기 바랍니다.**\n\n■ 오늘까지 흐름\n\n관련 이슈 누적 → 2026년 9월 9일 아침 「엘지에너지솔루션이 348,500원(−3.86%)으로 시총 상위 가운데 큰 폭으로 빠졌습니다」 기록 → 실측·수급·일정을 분리.\n\n■ 장기 투자 관점\n\n이 테마는 하루 등락이 아니라 수년 사이클입니다. 오늘 종가·통계는 스냅샷입니다.\n\n3~5년 뷰에서 유리한 점은 반복 데이터로 불확실성이 줄어드는 구간입니다.\n\n해자는 산업 구조·제도·현금흐름이 겹칠 때 두꺼워집니다.\n\n■ 앞으로 볼 것\n\n(1) 동일 정의의 후속 숫자를 기록하시기 바랍니다.\n\n(2) 수급·주체별 플로를 보시면 됩니다.\n\n(3) 캘린더 이벤트를 표에 두시기 바랍니다.\n\n(4) 상대 성과를 적으시기 바랍니다.\n\n(5) 빈칸 지표를 명시하시면 됩니다.\n\n\n\n추가로, 이번 이슈는 같은 주의 유가·금리·수급·정책 캘린더와 같이 보시면 해석이 안정됩니다. 개별 숫자만 확대경으로 보지 마시고 상대 성과와 빈칸 지표를 같은 노트에 남기시기 바랍니다.\n■ 투자시사점\n\n포트폴리오에서는 실측·수급·의견을 칸으로 나누시기 바랍니다. 하루 등락만으로 비중을 크게 바꾸지 마시기 바랍니다.\n\n레버리지는 물가·회의·리밸런싱 일정 앞에서 보수적으로 두시는 편이 안전합니다.\n\ninvestus.kr SRP 최고투자책임자 발행",
